/**
 * bytes.mjs — low-level byte helpers for the pure-JS JOSE port.
 *
 * Everything in here is hand-rolled plain-JS bit arithmetic on purpose: no
 * Buffer, no TextEncoder, no TextDecoder, no builtin modules at all. That keeps
 * the whole library provably self-contained and dependency free.
 *
 * A "byte string" in this library is always a Uint8Array. JavaScript strings are
 * UTF-16 code unit sequences, so the encoder below is responsible for pairing
 * surrogates back into astral code points before emitting UTF-8.
 */

/** Bytes of U+FFFD REPLACEMENT CHARACTER, used for every ill-formed sequence. */
const REPLACEMENT_BYTES = [0xef, 0xbf, 0xbd];

/** U+FFFD as a code unit, emitted by the decoder on malformed input. */
const REPLACEMENT_CODE_UNIT = 0xfffd;

/** Flush the decoder's code-unit accumulator this often to bound memory/stack. */
const STRING_CHUNK_SIZE = 4096;

/**
 * Encode a JavaScript string to UTF-8 bytes (FIPS-agnostic, RFC 3629).
 *
 * - U+0000..U+007F      -> 1 byte  0xxxxxxx
 * - U+0080..U+07FF      -> 2 bytes 110xxxxx 10xxxxxx
 * - U+0800..U+FFFF      -> 3 bytes 1110xxxx 10xxxxxx 10xxxxxx
 * - U+10000..U+10FFFF   -> 4 bytes 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
 *   (reached through a well-formed high/low UTF-16 surrogate pair)
 *
 * An unpaired surrogate (a lone high surrogate, or a low surrogate with no
 * preceding high surrogate) is not a valid scalar value, so it is replaced by
 * the three bytes of U+FFFD rather than being encoded as CESU-8.
 *
 * @param {string} str input text
 * @returns {Uint8Array} the UTF-8 encoding of `str`
 */
export function utf8Encode(str) {
  const text = typeof str === 'string' ? str : String(str);
  const out = [];

  for (let i = 0; i < text.length; i += 1) {
    let codePoint = text.charCodeAt(i);

    // Resolve surrogates into a scalar value before doing any bit work.
    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      // High surrogate: only valid when directly followed by a low surrogate.
      const next = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
      if (next >= 0xdc00 && next <= 0xdfff) {
        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + (next - 0xdc00);
        i += 1; // the low surrogate is consumed as part of this code point
      } else {
        pushAll(out, REPLACEMENT_BYTES);
        continue;
      }
    } else if (codePoint >= 0xdc00 && codePoint <= 0xdfff) {
      // Lone low surrogate: never valid on its own.
      pushAll(out, REPLACEMENT_BYTES);
      continue;
    }

    if (codePoint <= 0x7f) {
      out.push(codePoint);
    } else if (codePoint <= 0x7ff) {
      out.push(0xc0 | (codePoint >> 6));
      out.push(0x80 | (codePoint & 0x3f));
    } else if (codePoint <= 0xffff) {
      out.push(0xe0 | (codePoint >> 12));
      out.push(0x80 | ((codePoint >> 6) & 0x3f));
      out.push(0x80 | (codePoint & 0x3f));
    } else {
      out.push(0xf0 | (codePoint >> 18));
      out.push(0x80 | ((codePoint >> 12) & 0x3f));
      out.push(0x80 | ((codePoint >> 6) & 0x3f));
      out.push(0x80 | (codePoint & 0x3f));
    }
  }

  return new Uint8Array(out);
}

/**
 * Decode UTF-8 bytes back into a JavaScript string.
 *
 * The decoder is strict about well-formedness and substitutes one U+FFFD for
 * every maximal ill-formed subsequence (the same policy as the WHATWG encoding
 * standard). Rejected and replaced:
 *
 * - stray continuation bytes (0x80..0xBF) and invalid lead bytes (0xC0, 0xC1,
 *   0xF5..0xFF)
 * - overlong forms, via the narrowed second-byte range per lead byte
 *   (0xE0 needs 0xA0..0xBF, 0xF0 needs 0x90..0xBF, ...)
 * - UTF-16 surrogates encoded as 3 bytes (0xED 0xA0..0xBF ...)
 * - code points above U+10FFFF (0xF4 only accepts 0x80..0x8F)
 * - truncated sequences, including one cut off at the end of the input
 *
 * When a continuation byte turns out to be invalid it is *not* consumed: it is
 * re-examined as a potential lead byte, so "\xE0\x41" decodes to U+FFFD + "A".
 *
 * @param {Uint8Array|number[]} bytes UTF-8 encoded input
 * @returns {string} the decoded text
 */
export function utf8Decode(bytes) {
  const input = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes || []);
  const pieces = [];
  let units = [];
  let i = 0;

  while (i < input.length) {
    const lead = input[i];

    // Fast path: plain ASCII is one byte, one code unit.
    if (lead <= 0x7f) {
      units.push(lead);
      i += 1;
      units = maybeFlush(pieces, units);
      continue;
    }

    // Work out how many trailing bytes follow and how wide the second byte may
    // be. The narrowed lower/upper bounds are what makes overlong sequences,
    // surrogates and out-of-range code points fail here instead of silently
    // decoding.
    let needed = 0;
    let lowerBound = 0x80;
    let upperBound = 0xbf;
    let codePoint = 0;

    if (lead >= 0xc2 && lead <= 0xdf) {
      needed = 1;
      codePoint = lead & 0x1f;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      needed = 2;
      codePoint = lead & 0x0f;
      if (lead === 0xe0) {
        lowerBound = 0xa0; // reject overlong 3-byte forms of U+0000..U+07FF
      } else if (lead === 0xed) {
        upperBound = 0x9f; // reject the surrogate range U+D800..U+DFFF
      }
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      needed = 3;
      codePoint = lead & 0x07;
      if (lead === 0xf0) {
        lowerBound = 0x90; // reject overlong 4-byte forms of U+0000..U+FFFF
      } else if (lead === 0xf4) {
        upperBound = 0x8f; // reject code points above U+10FFFF
      }
    } else {
      // 0x80..0xC1 and 0xF5..0xFF can never start a sequence.
      units.push(REPLACEMENT_CODE_UNIT);
      i += 1;
      units = maybeFlush(pieces, units);
      continue;
    }

    let consumed = 1;
    let valid = true;

    for (let n = 0; n < needed; n += 1) {
      const index = i + 1 + n;
      const byte = index < input.length ? input[index] : -1;
      const min = n === 0 ? lowerBound : 0x80;
      const max = n === 0 ? upperBound : 0xbf;

      if (byte < min || byte > max) {
        // Truncated or invalid: emit one U+FFFD for the maximal subpart we saw
        // and leave the offending byte for the next iteration.
        valid = false;
        break;
      }

      codePoint = (codePoint << 6) | (byte & 0x3f);
      consumed += 1;
    }

    if (!valid) {
      units.push(REPLACEMENT_CODE_UNIT);
      i += consumed;
      units = maybeFlush(pieces, units);
      continue;
    }

    i += consumed;

    if (codePoint <= 0xffff) {
      units.push(codePoint);
    } else {
      // Split the astral code point back into a UTF-16 surrogate pair.
      const offset = codePoint - 0x10000;
      units.push(0xd800 + (offset >> 10));
      units.push(0xdc00 + (offset & 0x3ff));
    }

    units = maybeFlush(pieces, units);
  }

  if (units.length > 0) {
    pieces.push(String.fromCharCode.apply(null, units));
  }

  return pieces.join('');
}

/**
 * Encode a string as latin-1 / binary bytes: keep only the low byte of every
 * UTF-16 code unit. Used where a "byte string" is already held in a JS string
 * (base64 intermediates, raw signature material) and no transcoding is wanted.
 *
 * @param {string} str input whose code units are treated as byte values
 * @returns {Uint8Array} one byte per input code unit
 */
export function latin1Encode(str) {
  const text = typeof str === 'string' ? str : String(str);
  const out = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i += 1) {
    out[i] = text.charCodeAt(i) & 0xff;
  }
  return out;
}

/**
 * Concatenate a list of byte arrays into one fresh Uint8Array.
 *
 * @param {Array<Uint8Array|number[]>} list byte arrays to join, in order
 * @returns {Uint8Array} the concatenation
 */
export function concatBytes(list) {
  const parts = (list || []).map((part) =>
    part instanceof Uint8Array ? part : new Uint8Array(part || [])
  );

  let total = 0;
  for (const part of parts) {
    total += part.length;
  }

  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/**
 * Plain (non-timing-safe) byte comparison. Use this for structural checks only;
 * signature comparison goes through the timing-safe helper in hmac.mjs.
 *
 * @param {Uint8Array|number[]} a first operand
 * @param {Uint8Array|number[]} b second operand
 * @returns {boolean} true when both have the same length and the same bytes
 */
export function bytesEqual(a, b) {
  const left = a instanceof Uint8Array ? a : new Uint8Array(a || []);
  const right = b instanceof Uint8Array ? b : new Uint8Array(b || []);

  if (left.length !== right.length) {
    return false;
  }
  for (let i = 0; i < left.length; i += 1) {
    if (left[i] !== right[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Append every element of `src` to `dst` (small helper to keep the encoder
 * loop free of spread allocations).
 *
 * @param {number[]} dst accumulator being appended to
 * @param {number[]} src values to append
 */
function pushAll(dst, src) {
  for (let i = 0; i < src.length; i += 1) {
    dst.push(src[i]);
  }
}

/**
 * Turn the decoder's code-unit accumulator into a string chunk once it grows
 * past STRING_CHUNK_SIZE, so `String.fromCharCode.apply` never sees an argument
 * list large enough to overflow the call stack.
 *
 * @param {string[]} pieces collected string chunks
 * @param {number[]} units pending UTF-16 code units
 * @returns {number[]} the accumulator to keep using (empty after a flush)
 */
function maybeFlush(pieces, units) {
  if (units.length >= STRING_CHUNK_SIZE) {
    pieces.push(String.fromCharCode.apply(null, units));
    return [];
  }
  return units;
}

// bytes_mjs_check.mjs — scratch verification for /output/lib/bytes.mjs
// Compares the hand-rolled encoder/decoder against Node's builtins (allowed
// here in the scratch harness only, never in the deliverable).
import {
  utf8Encode,
  utf8Decode,
  latin1Encode,
  concatBytes,
  bytesEqual,
} from '/output/lib/bytes.mjs';

const te = new TextEncoder();
const td = new TextDecoder('utf-8'); // WHATWG replacement policy

let fails = 0;
function check(name, actual, expected) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    fails += 1;
    console.log(`FAIL ${name}\n  got      ${a}\n  expected ${e}`);
  }
}

function hex(bytes) {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join(' ');
}

// ---- encoder vs TextEncoder over a fixed corpus -----------------------------
const corpus = [
  '',
  'a',
  'iat_data_5',
  'hello world',
  '�',
  '߿',
  'ࠀ￿',
  '😀',        // U+1F600
  'emoji😀',
  '中文测试',
  'accént',
  'nbsp x',
  'zw​space',
  '\ud800',              // lone high surrogate
  '\udfff',              // lone low surrogate
  'a\ud800b',
  'a\udc00\ud800b',
  '\ud83d😀',  // high, then a valid pair
  '😀\ude00',
  '\u{10ffff}',
  'lt<gt>amp&/slash',
  'a"b\\c\'d',
];

for (const s of corpus) {
  check(`encode ${JSON.stringify(s)}`, Array.from(utf8Encode(s)), Array.from(te.encode(s)));
}

// ---- decoder vs TextDecoder: malformed byte cases ---------------------------
const badSeqs = [
  [],
  [0x41],
  [0x80],                          // stray continuation
  [0xbf],
  [0xc0, 0x80],                    // overlong NUL
  [0xc1, 0xbf],                    // overlong
  [0xc2],                          // truncated 2-byte
  [0xc2, 0x41],                    // bad continuation -> resync on 'A'
  [0xe0, 0x80, 0x80],              // overlong 3-byte
  [0xe0, 0x9f, 0xbf],              // overlong boundary
  [0xe0, 0xa0, 0x80],              // U+0800, valid
  [0xe0, 0x41],
  [0xe1, 0x80],                    // truncated
  [0xed, 0xa0, 0x80],              // surrogate U+D800
  [0xed, 0x9f, 0xbf],              // U+D7FF valid
  [0xee, 0x80, 0x80],
  [0xef, 0xbf, 0xbd],
  [0xf0, 0x80, 0x80, 0x80],        // overlong 4-byte
  [0xf0, 0x8f, 0xbf, 0xbf],        // overlong boundary
  [0xf0, 0x90, 0x80, 0x80],        // U+10000 valid
  [0xf4, 0x8f, 0xbf, 0xbf],        // U+10FFFF valid
  [0xf4, 0x90, 0x80, 0x80],        // > U+10FFFF
  [0xf5, 0x80, 0x80, 0x80],
  [0xf8, 0x88, 0x80, 0x80, 0x80],  // 5-byte form
  [0xfe],
  [0xff],
  [0xf0, 0x9f, 0x98],              // truncated emoji
  [0xf0, 0x9f, 0x98, 0x41],
  [0x41, 0xc2, 0xa9, 0x42],
  [0xe2, 0x82, 0xac],              // U+20AC
  [0xc2, 0xc2, 0xa9],
  [0xed, 0xa0, 0x80, 0xed, 0xb0, 0x80], // CESU-8 pair
];

for (const seq of badSeqs) {
  const bytes = new Uint8Array(seq);
  check(`decode [${hex(bytes)}]`, utf8Decode(bytes), td.decode(bytes));
}

// ---- round trips ------------------------------------------------------------
for (const s of corpus) {
  const rt = utf8Decode(utf8Encode(s));
  check(`roundtrip ${JSON.stringify(s)}`, rt, td.decode(te.encode(s)));
}

// ---- random fuzz: encode side ----------------------------------------------
function randomString(len) {
  let s = '';
  for (let i = 0; i < len; i += 1) {
    s += String.fromCharCode(Math.floor(Math.random() * 0x11000) % 0x10000);
  }
  return s;
}
for (let t = 0; t < 3000; t += 1) {
  const s = randomString(1 + Math.floor(Math.random() * 12));
  const mine = Array.from(utf8Encode(s));
  const ref = Array.from(te.encode(s));
  if (JSON.stringify(mine) !== JSON.stringify(ref)) {
    fails += 1;
    console.log(`FAIL fuzz-encode ${JSON.stringify(s)}\n  got ${mine}\n  exp ${ref}`);
    break;
  }
}

// ---- random fuzz: decode side ----------------------------------------------
for (let t = 0; t < 5000; t += 1) {
  const len = 1 + Math.floor(Math.random() * 10);
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i += 1) {
    bytes[i] = Math.floor(Math.random() * 256);
  }
  const mine = utf8Decode(bytes);
  const ref = td.decode(bytes);
  if (mine !== ref) {
    fails += 1;
    console.log(`FAIL fuzz-decode [${hex(bytes)}]\n  got ${JSON.stringify(mine)}\n  exp ${JSON.stringify(ref)}`);
    break;
  }
}

// ---- fuzz with a biased alphabet that produces more near-valid sequences ----
const leadPool = [0x41, 0x7f, 0x80, 0xbf, 0xc0, 0xc2, 0xdf, 0xe0, 0xa0, 0xed, 0xef, 0xf0, 0x90, 0xf4, 0x8f, 0xf5, 0xff];
for (let t = 0; t < 20000; t += 1) {
  const len = 1 + Math.floor(Math.random() * 8);
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i += 1) {
    bytes[i] = leadPool[Math.floor(Math.random() * leadPool.length)];
  }
  const mine = utf8Decode(bytes);
  const ref = td.decode(bytes);
  if (mine !== ref) {
    fails += 1;
    console.log(`FAIL fuzz2-decode [${hex(bytes)}]\n  got ${JSON.stringify(mine)}\n  exp ${JSON.stringify(ref)}`);
    break;
  }
}

// ---- long input crosses the chunk-flush boundary ---------------------------
const long = '中😀a'.repeat(5000);
check('long roundtrip', utf8Decode(utf8Encode(long)) === long, true);
check('long length', utf8Encode(long).length, te.encode(long).length);

// ---- latin1Encode ----------------------------------------------------------
check('latin1 ascii', Array.from(latin1Encode('abc')), [97, 98, 99]);
check('latin1 truncates', Array.from(latin1Encode('ÿĀ中')), [0xff, 0x00, 0x2d]);
check('latin1 empty', Array.from(latin1Encode('')), []);

// ---- concatBytes -----------------------------------------------------------
check('concat', Array.from(concatBytes([new Uint8Array([1, 2]), new Uint8Array([]), new Uint8Array([3])])), [1, 2, 3]);
check('concat empty list', Array.from(concatBytes([])), []);
check('concat arrays', Array.from(concatBytes([[1], [2, 3]])), [1, 2, 3]);

// ---- bytesEqual ------------------------------------------------------------
check('eq same', bytesEqual(new Uint8Array([1, 2]), new Uint8Array([1, 2])), true);
check('eq diff len', bytesEqual(new Uint8Array([1]), new Uint8Array([1, 2])), false);
check('eq diff byte', bytesEqual(new Uint8Array([1, 2]), new Uint8Array([1, 3])), false);
check('eq empty', bytesEqual(new Uint8Array([]), new Uint8Array([])), true);

// ---- the actual JWT signing input for the reference token ------------------
const header = '{"alg":"HS256","typ":"JWT"}';
check('header bytes', hex(utf8Encode(header)), hex(te.encode(header)));

console.log(fails === 0 ? 'ALL BYTES CHECKS PASSED' : `${fails} FAILURE(S)`);

